import 'package:flutter/material.dart'; import '../models/poll.dart'; import '../widgets/page_frame.dart';
class ResultsScreen extends StatelessWidget { const ResultsScreen({super.key, required this.poll}); final Poll poll; @override Widget build(BuildContext context) { final max = poll.candidates.map((c) => c.votes).reduce((a,b) => a>b?a:b); final winners = poll.candidates.where((c) => c.votes == max).toList(); return PageFrame(title: 'Results', onBack: () => Navigator.pop(context), child: ListView(padding: const EdgeInsets.all(24), children: [Text(poll.title, style: const TextStyle(fontSize: 28, fontWeight: FontWeight.bold)), const SizedBox(height: 14), if (poll.status != PollStatus.published) const Card(child: Padding(padding: EdgeInsets.all(16), child: Text('Results are visible to the creator only until they are published.'))), if (poll.status == PollStatus.published) Card(color: Colors.amber.shade100, child: Padding(padding: const EdgeInsets.all(16), child: Text(winners.length == 1 ? 'Winner: ${winners.first.name}' : 'Tie: ${winners.map((w) => w.name).join(', ')}', style: const TextStyle(fontSize: 20, fontWeight: FontWeight.bold)))), for (final c in poll.candidates) ListTile(title: Text(c.name), subtitle: LinearProgressIndicator(value: poll.totalVotes == 0 ? 0 : c.votes/poll.totalVotes), trailing: Text('${c.votes}'))])); } }
